import vuedraggable from 'vuedraggable';
import linkaddress from '@/components/linkaddress';
export default {
  name: 'c_tab_list',
  props: {
    configObj: {
      type: Object
    },
    configNme: {
      type: String
    },
    index: {
      type: null
    }
  },
  components: {
    linkaddress: linkaddress,
    draggable: vuedraggable
  },
  data: function data() {
    return {
      defaults: {},
      configData: {},
      itemObj: {},
      activeIndex: 0
    };
  },
  mounted: function mounted() {
    var _this = this;
    this.$nextTick(function () {
      _this.defaults = _this.configObj;
      _this.configData = _this.configObj[_this.configNme];
    });
  },
  watch: {
    configObj: {
      handler: function handler(nVal, oVal) {
        this.defaults = nVal;
        this.configData = nVal[this.configNme];
      },
      deep: true
    }
  },
  methods: {
    linkUrl: function linkUrl(e) {
      if (this.configData.list[this.activeIndex].dataType.tabVal) {
        var obj = e.split('?')[1];
        var obj2 = obj.split('&');
        this.configData.list[this.activeIndex].classPage.name = obj2[1].split('=')[1];
        this.configData.list[this.activeIndex].classPage.id = obj2[0].split('=')[1];
      } else {
        var _obj = e.split('?')[1];
        var _obj2 = _obj.split('&');
        this.configData.list[this.activeIndex].microPage.name = _obj2[1].split('=')[1];
        this.configData.list[this.activeIndex].microPage.id = _obj2[0].split('=')[1];
      }
    },
    getLink: function getLink(index) {
      this.activeIndex = index;
      var obj = {};
      if (this.configData.list[this.activeIndex].dataType.tabVal) {
        obj = {
          id: 8,
          pid: 2,
          type: "product_category"
        };
      } else {
        obj = {
          id: 7,
          pid: 1,
          type: "special"
        };
      }
      this.$refs.linkaddres.handleCheckChange('', obj);
      this.$refs.linkaddres.modals = true;
    },
    addHotTxt: function addHotTxt() {
      if (this.configData.list.length == 0) {
        var storage = window.localStorage;
        this.itemObj = JSON.parse(storage.getItem('itemObj'));
        this.itemObj.dataType.tabVal = 0;
        this.itemObj.microPage.name = '';
        this.itemObj.classPage.name = '';
        this.configData.list.push(this.itemObj);
      } else {
        var obj = JSON.parse(JSON.stringify(this.configData.list[this.configData.list.length - 1]));
        obj.dataType.tabVal = 0;
        obj.microPage.name = '';
        obj.classPage.name = '';
        this.configData.list.push(obj);
      }
    },
    // 删除数组
    bindDelete: function bindDelete(index) {
      if (this.configData.list.length == 1) {
        var itemObj = this.configData.list[0];
        this.itemObj = itemObj;
        var storage = window.localStorage;
        storage.setItem('itemObj', JSON.stringify(itemObj));
      }
      this.configData.list.splice(index, 1);
    }
  }
};
